# ---- Parents page: add parents by email ----
R('<p class="lede">Parent accounts, the children they can see, siblings and invite codes.</p></div><button class="btn btn-ghost btn-sm" data-act="inviteHelp">${ic("link")}How invites work</button></div>',
  '<p class="lede">Add parents by email and pick their children. They sign in with that email and see their children straight away.</p></div><div class="row"><button class="btn btn-ghost btn-sm" data-act="inviteHelp">${ic("link")}How it works</button><button class="btn btn-primary" data-act="addParent">${ic("userplus")}Add parent</button></div></div>')
R('  <section class="card panel"><div class="toolbar"><input class="search" id="q" type="search" placeholder="Search parents or children" aria-label="Search parents">',
  '  ${parentsOnFileHTML()}\n  <section class="card panel"><h2>Signed-in parent accounts</h2><div class="toolbar"><input class="search" id="q" type="search" placeholder="Search parents or children" aria-label="Search parents">')
R('emptyBox("No parent accounts yet","Send a parent their child\'s invite code. When they sign in and choose Parent, they appear here.","","pip")',
  'emptyBox("No parent accounts yet","Parents appear here once they sign in for the first time.","","pip")')
R('A.inviteHelp=()=>openModal("How parent invites work",`<ol class="steps"><li>Open a learner\'s details and copy their invite message. It has the classroom link and a 6-letter code.</li><li>Send it to the parent on WhatsApp or email.</li><li>The parent signs in, chooses <b>Parent</b> and enters the code.</li><li>They appear under <b>Waiting to be connected</b> with their child already picked. Press Connect.</li></ol>',
  'A.inviteHelp=()=>openModal("How parent logins work",`<ol class="steps"><li>Press <b>Add parent</b>, type their name and email, and tick their children.</li><li>Send them the invite on WhatsApp or email (buttons in the list).</li><li>They open the classroom link, type that email and enter the 6-digit code they receive.</li><li>They land straight on their child\'s dashboard, and the status changes to <b>Signed in</b>.</li></ol><p class="small">If a parent signs in with a different email, they show under <b>Waiting to be connected</b>. Press Connect there, or add that email to them.</p>')
R('/* ================= events ================= */',open(W+'parents_block.js').read()+'\n/* ================= events ================= */')
